def minimum_triple_bit_flips(nums):
    nums=nums[:];operations=0
    for index in range(len(nums)-2):
        if nums[index]==0:
            operations+=1
            for changed in range(index,index+3):nums[changed]^=1
    return operations if all(nums) else -1

